import pandas as pd, numpy as np
d=pd.read_csv('data/allBirthData.csv',dtype={'State':str,'County':str})
d['C']=d.County.str.zfill(5); d['S']=np.where(d.County.notna(), d.C.str[:2], None)
def state_series(f):
    s=d[d.S==f].drop_duplicates(subset=['Year','Month'])
    return s.groupby('Year').stateBirths.sum()
for f in ['12','23','36','25','40','26']:
    print(f, state_series(f).loc[[1995,2005,2015]].to_dict())
